-- User
CREATE TABLE IF NOT EXISTS `Users` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(255) NOT NULL, `email` VARCHAR(255) NOT NULL UNIQUE, `password` VARCHAR(255) NOT NULL, `role` ENUM('admin', 'cashier', 'kitchen', 'inventory') NOT NULL DEFAULT 'cashier', `status` ENUM('pending', 'approved', 'rejected', 'inactive') NOT NULL DEFAULT 'pending', `assignedCategories` JSON, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;

-- MenuCategory
CREATE TABLE IF NOT EXISTS `menu_categories` (`id` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL UNIQUE, `description` TEXT, `icon` VARCHAR(255) DEFAULT 'dish', `itemCount` INTEGER NOT NULL DEFAULT 0, `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'active', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;

-- MenuItem
CREATE TABLE IF NOT EXISTS `menu_items` (`id` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL, `categoryId` INTEGER NOT NULL, `price` DECIMAL(10,2) NOT NULL, `description` TEXT, `hasSize` TINYINT(1) NOT NULL DEFAULT false, `sizes` JSON, `hasFlavor` TINYINT(1) NOT NULL DEFAULT false, `flavors` JSON, `hasTemperature` TINYINT(1) NOT NULL DEFAULT false, `temperatures` JSON, `status` ENUM('available', 'unavailable') NOT NULL DEFAULT 'available', `inventoryMode` ENUM('prepared', 'recipe') NOT NULL DEFAULT 'prepared', `reservedStock` INTEGER NOT NULL DEFAULT 0, `reorderLevel` INTEGER NOT NULL DEFAULT 10, `trackStock` TINYINT(1) NOT NULL DEFAULT true, `stock` INTEGER NOT NULL DEFAULT 0, `defaultStock` INTEGER NOT NULL DEFAULT 0, `lastStockReset` DATE DEFAULT NULL, `archived` TINYINT(1) NOT NULL DEFAULT false, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`categoryId`) REFERENCES `menu_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;

-- Order
CREATE TABLE IF NOT EXISTS `Orders` (`id` INTEGER NOT NULL auto_increment , `clientRequestId` VARCHAR(128) UNIQUE, `orderNumber` VARCHAR(255) NOT NULL UNIQUE, `cashierId` INTEGER, `preparedById` INTEGER COMMENT 'Kitchen staff who prepared this order', `customerName` VARCHAR(255), `subtotal` DECIMAL(10,2) NOT NULL DEFAULT 0, `discount` DECIMAL(10,2) NOT NULL DEFAULT 0, `total` DECIMAL(10,2) NOT NULL DEFAULT 0, `status` ENUM('pending', 'preparing', 'ready', 'completed', 'cancelled') NOT NULL DEFAULT 'pending', `completedAt` DATETIME DEFAULT NULL, `orderType` ENUM('dine-in', 'take-out', 'delivery') DEFAULT NULL, `tableNumber` VARCHAR(255) DEFAULT NULL, `deliveryAddress` TEXT, `notes` TEXT, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`cashierId`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (`preparedById`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;

-- OrderItem
CREATE TABLE IF NOT EXISTS `OrderItems` (`id` INTEGER NOT NULL auto_increment , `orderId` INTEGER NOT NULL, `menuItemId` INTEGER, `name` VARCHAR(255) NOT NULL, `price` DECIMAL(10,2) NOT NULL, `quantity` INTEGER NOT NULL DEFAULT 1, `total` DECIMAL(10,2) NOT NULL, `modifiers` JSON, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`orderId`) REFERENCES `Orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (`menuItemId`) REFERENCES `menu_items` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;

-- Payment
CREATE TABLE IF NOT EXISTS `Payments` (`id` INTEGER NOT NULL auto_increment , `orderId` INTEGER NOT NULL, `method` ENUM('cash', 'card', 'digital') NOT NULL, `amount` DECIMAL(10,2) NOT NULL, `amountReceived` DECIMAL(10,2), `change` DECIMAL(10,2), `status` ENUM('completed', 'failed') NOT NULL DEFAULT 'completed', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`orderId`) REFERENCES `Orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;

-- Log
CREATE TABLE IF NOT EXISTS `Logs` (`id` INTEGER NOT NULL auto_increment , `userId` INTEGER COMMENT 'ID of the user who performed the action', `userName` VARCHAR(255) COMMENT 'Name of the user for easier identification', `action` ENUM('CREATE_ORDER', 'UPDATE_ORDER', 'DELETE_ORDER', 'CREATE_EMPLOYEE', 'UPDATE_EMPLOYEE', 'DELETE_EMPLOYEE', 'CREATE_MENU_ITEM', 'UPDATE_MENU_ITEM', 'DELETE_MENU_ITEM', 'CREATE_MENU_CATEGORY', 'UPDATE_MENU_CATEGORY', 'DELETE_MENU_CATEGORY', 'LOGIN', 'LOGOUT', 'UPDATE_PASSWORD', 'UPDATE_PROFILE', 'ASSIGN_STATION', 'ASSIGN_CATEGORIES', 'OTHER') NOT NULL COMMENT 'Type of action performed', `module` VARCHAR(255) NOT NULL COMMENT 'Module affected (orders, employees, menu, etc.)', `entityId` INTEGER COMMENT 'ID of the entity affected by the action', `entityType` VARCHAR(255) COMMENT 'Type of entity (Order, Employee, MenuItem, etc.)', `description` TEXT COMMENT 'Detailed description of the action', `changes` JSON COMMENT 'Before/after values for update actions', `ipAddress` VARCHAR(255) COMMENT 'IP address of the requester', `status` ENUM('success', 'failed', 'pending') NOT NULL DEFAULT 'success' COMMENT 'Whether the action succeeded or failed', `errorMessage` TEXT COMMENT 'Error message if action failed', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
ALTER TABLE `Logs` ADD INDEX `logs_user_id` (`userId`);
ALTER TABLE `Logs` ADD INDEX `logs_action` (`action`);
ALTER TABLE `Logs` ADD INDEX `logs_module` (`module`);
ALTER TABLE `Logs` ADD INDEX `logs_entity_type_entity_id` (`entityType`, `entityId`);
ALTER TABLE `Logs` ADD INDEX `logs_created_at` (`createdAt`);

-- InventorySettings
CREATE TABLE IF NOT EXISTS `inventory_settings` (`id` INTEGER NOT NULL auto_increment , `expiryWarningDays` INTEGER NOT NULL DEFAULT 7, `refreshSeconds` INTEGER NOT NULL DEFAULT 30, `defaultPreparedReorderLevel` INTEGER NOT NULL DEFAULT 10, `countApproval` ENUM('item_limits', 'admin_review') NOT NULL DEFAULT 'item_limits', `version` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;

-- Supplier
CREATE TABLE IF NOT EXISTS `inventory_suppliers` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(160) NOT NULL, `contact` VARCHAR(160), `email` VARCHAR(254), `phone` VARCHAR(40), `notes` TEXT, `active` TINYINT(1) NOT NULL DEFAULT true, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;

-- StockItem
CREATE TABLE IF NOT EXISTS `inventory_items` (`id` INTEGER NOT NULL auto_increment , `code` VARCHAR(64) NOT NULL UNIQUE, `name` VARCHAR(160) NOT NULL, `kind` ENUM('ingredient', 'packaging') NOT NULL, `unit` ENUM('pcs', 'g', 'ml') NOT NULL, `purchaseUnit` VARCHAR(40) NOT NULL, `unitsPerPurchase` DECIMAL(14,4) NOT NULL DEFAULT 1, `onHand` DECIMAL(14,4) NOT NULL DEFAULT 0, `reserved` DECIMAL(14,4) NOT NULL DEFAULT 0, `reorderLevel` DECIMAL(14,4) NOT NULL DEFAULT 0, `adjustmentLimit` DECIMAL(14,4), `location` VARCHAR(120), `supplierId` INTEGER, `archived` TINYINT(1) NOT NULL DEFAULT false, `version` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`supplierId`) REFERENCES `inventory_suppliers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;

-- StockBatch
CREATE TABLE IF NOT EXISTS `inventory_batches` (`id` INTEGER NOT NULL auto_increment , `stockItemId` INTEGER NOT NULL, `code` VARCHAR(80) NOT NULL, `onHand` DECIMAL(14,4) NOT NULL DEFAULT 0, `reserved` DECIMAL(14,4) NOT NULL DEFAULT 0, `unitCost` DECIMAL(14,4) NOT NULL DEFAULT 0, `expiryDate` DATE, `quarantined` TINYINT(1) NOT NULL DEFAULT false, `receivedAt` DATETIME NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`stockItemId`) REFERENCES `inventory_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;
ALTER TABLE `inventory_batches` ADD INDEX `inventory_batches_stock_item_id_expiry_date` (`stockItemId`, `expiryDate`);

-- StockReceipt
CREATE TABLE IF NOT EXISTS `inventory_receipts` (`id` INTEGER NOT NULL auto_increment , `number` VARCHAR(80) NOT NULL UNIQUE, `supplierId` INTEGER, `reference` VARCHAR(120), `notes` TEXT, `receivedAt` DATETIME NOT NULL, `userId` INTEGER NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`supplierId`) REFERENCES `inventory_suppliers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;

-- StockReceiptLine
CREATE TABLE IF NOT EXISTS `inventory_receipt_lines` (`id` INTEGER NOT NULL auto_increment , `receiptId` INTEGER NOT NULL, `stockItemId` INTEGER NOT NULL, `batchId` INTEGER NOT NULL, `purchaseQuantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `purchaseUnit` VARCHAR(40) NOT NULL, `conversion` DECIMAL(14,4) NOT NULL DEFAULT 1, `quantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `unitCost` DECIMAL(14,4) NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`receiptId`) REFERENCES `inventory_receipts` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`stockItemId`) REFERENCES `inventory_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`batchId`) REFERENCES `inventory_batches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;

-- StockMovement
CREATE TABLE IF NOT EXISTS `inventory_movements` (`id` INTEGER NOT NULL auto_increment , `stockItemId` INTEGER, `menuItemId` INTEGER, `batchId` INTEGER, `action` ENUM('opening', 'receive', 'reserve', 'consume', 'release', 'waste', 'count', 'supplier_return', 'reversal', 'hold', 'unhold') NOT NULL, `quantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `onHandDelta` DECIMAL(14,4) NOT NULL DEFAULT 0, `reservedDelta` DECIMAL(14,4) NOT NULL DEFAULT 0, `onHandBefore` DECIMAL(14,4) NOT NULL DEFAULT 0, `onHandAfter` DECIMAL(14,4) NOT NULL DEFAULT 0, `reservedBefore` DECIMAL(14,4) NOT NULL DEFAULT 0, `reservedAfter` DECIMAL(14,4) NOT NULL DEFAULT 0, `unit` VARCHAR(8) NOT NULL, `reason` TEXT NOT NULL, `userId` INTEGER NOT NULL, `orderId` INTEGER, `receiptId` INTEGER, `reversesId` INTEGER UNIQUE, `operationKey` VARCHAR(191) NOT NULL UNIQUE, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`stockItemId`) REFERENCES `inventory_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`menuItemId`) REFERENCES `menu_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`batchId`) REFERENCES `inventory_batches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`orderId`) REFERENCES `Orders` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;
ALTER TABLE `inventory_movements` ADD INDEX `inventory_movements_stock_item_id_created_at` (`stockItemId`, `createdAt`);
ALTER TABLE `inventory_movements` ADD INDEX `inventory_movements_order_id` (`orderId`);

-- MenuRecipe
CREATE TABLE IF NOT EXISTS `inventory_recipes` (`id` INTEGER NOT NULL auto_increment , `menuItemId` INTEGER NOT NULL, `label` VARCHAR(120) NOT NULL, `profileKey` VARCHAR(191) NOT NULL, `size` VARCHAR(80), `flavor` VARCHAR(80), `temperature` VARCHAR(40), `components` JSON NOT NULL, `version` INTEGER NOT NULL DEFAULT 1, `current` TINYINT(1) NOT NULL DEFAULT true, `userId` INTEGER NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`menuItemId`) REFERENCES `menu_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;
ALTER TABLE `inventory_recipes` ADD UNIQUE INDEX `inventory_recipes_menu_item_id_profile_key_version` (`menuItemId`, `profileKey`, `version`);

-- StockAllocation
CREATE TABLE IF NOT EXISTS `inventory_order_allocations` (`id` INTEGER NOT NULL auto_increment , `orderId` INTEGER NOT NULL UNIQUE, `state` ENUM('reserved', 'consumed', 'released', 'wasted') NOT NULL, `prepared` JSON NOT NULL, `supplies` JSON NOT NULL, `recipes` JSON NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`orderId`) REFERENCES `Orders` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;

