CREATE TABLE IF NOT EXISTS `inventory_counts` (`id` INTEGER NOT NULL auto_increment , `stockItemId` INTEGER NOT NULL, `batchId` INTEGER NOT NULL, `expectedVersion` INTEGER NOT NULL, `previousQuantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `countedQuantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `difference` DECIMAL(14,4) NOT NULL DEFAULT 0, `reason` TEXT NOT NULL, `status` ENUM('pending', 'applied', 'rejected', 'stale') NOT NULL, `userId` INTEGER NOT NULL, `reviewedById` INTEGER, `reviewedAt` DATETIME, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`stockItemId`) REFERENCES `inventory_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`batchId`) REFERENCES `inventory_batches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;

-- WasteReport
CREATE TABLE IF NOT EXISTS `inventory_waste_reports` (`id` INTEGER NOT NULL auto_increment , `stockItemId` INTEGER NOT NULL, `batchId` INTEGER, `quantity` DECIMAL(14,4) NOT NULL DEFAULT 0, `reason` TEXT NOT NULL, `status` ENUM('pending', 'accepted', 'rejected') NOT NULL DEFAULT 'pending', `userId` INTEGER NOT NULL, `reviewedById` INTEGER, `reviewedAt` DATETIME, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`stockItemId`) REFERENCES `inventory_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`batchId`) REFERENCES `inventory_batches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB;

