CREATE TABLE IF NOT EXISTS `inventory_operations` (`id` INTEGER NOT NULL auto_increment , `requestId` VARCHAR(128) NOT NULL UNIQUE, `kind` VARCHAR(40) NOT NULL, `fingerprint` VARCHAR(64) NOT NULL, `userId` INTEGER NOT NULL, `result` JSON, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;

